// Generated by esquadro: do not edit. The list of a resource: the API's
// filters, sorting, search and pages, all in the URL, so that it can be
// shared and Back works.
import { keepPreviousData, useQuery } from "@tanstack/react-query"
import { Link, useNavigate, useSearch } from "@tanstack/react-router"
import { Button } from "@/components/ui/button.tsx"
import { Input } from "@/components/ui/input.tsx"
import { Table, Td, Th } from "@/components/ui/table.tsx"
import { api } from "../api.ts"
import { format, t } from "./i18n.ts"
import { FieldValue } from "./show.tsx"
import type { Rec } from "./meta.ts"
import { columnField } from "./resource.ts"
import type { Resource } from "./resource.ts"

/** The list's state, in the URL. */
export interface ListSearch {
  page?: number
  q?: string
  sort?: string
  [filter: string]: string | number | undefined
}

/** Validates the list's URL: for the route's validateSearch. */
export function listSearch(search: Record<string, unknown>): ListSearch {
  const out: ListSearch = {}
  for (const [k, v] of Object.entries(search)) {
    if (k === "page") out.page = Number(v) > 0 ? Number(v) : undefined
    else if (typeof v === "string" || typeof v === "number") out[k] = v
  }
  return out
}

export function ResourceList({ resource }: { resource: Resource }) {
  const { meta } = resource
  const search = useSearch({ strict: false }) as ListSearch
  const navigate = useNavigate()
  const paged = meta.pagination.includes("page")
  const query: Record<string, unknown> = { ...search }
  if (paged) {
    query.page = search.page ?? 1
    query.per_page = 25
  }
  const list = useQuery({
    queryKey: [meta.name, "list", query],
    queryFn: () => meta.api(api as never).list(query),
    placeholderData: keepPreviousData,
  })
  const set = (changes: Partial<ListSearch>) =>
    navigate({ to: ".", search: (s: Record<string, unknown>) => ({ ...s, ...changes }) as never })

  const page = list.data
  const canCreate = page?.can.includes("create")
  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center gap-2">
        <h1 className="mr-auto text-xl font-semibold">{meta.label}</h1>
        {resource.table.search !== false && meta.sorts.includes("relevance") && (
          <Input
            className="w-64"
            placeholder={t("search")}
            defaultValue={search.q ?? ""}
            onKeyDown={(e) => {
              if (e.key === "Enter") set({ q: e.currentTarget.value || undefined, page: undefined })
            }}
          />
        )}
        {canCreate && (
          <Button asLink>
            <Link to={`/${meta.name}/new` as never}>{t("new")}</Link>
          </Button>
        )}
      </div>
      {resource.table.filters && resource.table.filters.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {resource.table.filters.map((f) => (
            <select
              key={f.name}
              className="rounded-md border border-border bg-background px-2 py-1 text-sm"
              value={String(search[f.name] ?? "")}
              onChange={(e) => set({ [f.name]: e.target.value || undefined, page: undefined })}
            >
              <option value="">{f.label}: {t("all")}</option>
              {(f.values ?? ["true", "false"]).map((v) => (
                <option key={v} value={v}>
                  {f.kind === "bool" ? format(f, v === "true") : v}
                </option>
              ))}
            </select>
          ))}
        </div>
      )}
      <Table>
        <thead>
          <tr>
            {resource.table.columns.map((c) => {
              const f = columnField(c)
              const sortable = meta.sorts.includes(f.name)
              const label = "field" in c && c.label ? c.label : f.label
              return (
                <Th
                  key={f.name}
                  onClick={sortable ? () => set({ sort: search.sort === f.name ? `-${f.name}` : f.name }) : undefined}
                  className={sortable ? "cursor-pointer select-none" : undefined}
                >
                  {label}
                  {search.sort === f.name ? " ↑" : search.sort === `-${f.name}` ? " ↓" : ""}
                </Th>
              )
            })}
          </tr>
        </thead>
        <tbody>
          {list.isPending &&
            [0, 1, 2].map((i) => (
              <tr key={i}>
                <Td colSpan={resource.table.columns.length}>
                  <div className="h-4 animate-pulse rounded bg-muted" />
                </Td>
              </tr>
            ))}
          {page?.items.length === 0 && (
            <tr>
              <Td colSpan={resource.table.columns.length} className="py-8 text-center text-muted-foreground">
                {t("empty")}
              </Td>
            </tr>
          )}
          {page?.items.map((record: Rec) => (
            <tr
              key={record.id}
              className="cursor-pointer hover:bg-muted"
              onClick={() => navigate({ to: `/${meta.name}/${record.id}` as never })}
            >
              {resource.table.columns.map((c) => {
                const f = columnField(c)
                return <Td key={f.name}>{"field" in c && c.cell ? c.cell(record) : <FieldValue field={f} record={record} />}</Td>
              })}
            </tr>
          ))}
        </tbody>
      </Table>
      {list.isError && <p className="text-destructive">{t("somethingWrong")}</p>}
      {paged && page?.total_pages !== undefined && page.total_pages > 1 && (
        <div className="flex items-center justify-end gap-2 text-sm">
          <Button variant="outline" disabled={(search.page ?? 1) <= 1} onClick={() => set({ page: (search.page ?? 1) - 1 })}>
            {t("previous")}
          </Button>
          <span>{t("pageOf", { page: search.page ?? 1, pages: page.total_pages })}</span>
          <Button
            variant="outline"
            disabled={(search.page ?? 1) >= page.total_pages}
            onClick={() => set({ page: (search.page ?? 1) + 1 })}
          >
            {t("next")}
          </Button>
        </div>
      )}
    </div>
  )
}
